{
  "PROP-6a4369e9-inv-012": {
    "property_id": "PROP-6a4369e9-inv-012",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-012",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/validate_data_column.go::validateDataColumn::L157-158",
      "proof_trace": "TOCTOU race: hasSeenDataColumnIndex check (L157) happens during validation, but setSeenDataColumnIndex (subscriber_data_column_sidecar.go:42) only executes after ValidationAccept is returned and the handler runs. Two identical sidecars arriving concurrently both pass the check before either is marked as seen, allowing duplicate acceptance.",
      "attack_scenario": "Attacker broadcasts two identical data column sidecars to different peers; both arrive at victim node simultaneously, pass validation concurrently (both see cache miss), both return ValidationAccept before either marks the tuple as seen in the cache, resulting in duplicate acceptance.",
      "checklist_id": "PROP-6a4369e9-inv-012"
    },
    "text": "Deduplication key (slot, proposer_index, sidecar.index) must prevent duplicate acceptance.",
    "assertion": "forall s1,s2: accepted(s1) && accepted(s2) && same_dedup_key(s1,s2) => s1 == s2",
    "covers": "SG-006",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

